diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..72ef187 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,28 @@ export interface Record {
   warns: readonly string[];
 }

+const deduplicate = (entries: readonly string[]): string[] => {
+  const seen = new Set<string>();
+  const result: string[] = [];
+
+  for (const entry of entries) {
+    // Normalize: lowercase, trim, collapse repeated whitespace
+    const normalized = entry.toLowerCase().trim().replace(/\s+/g, ' ');
+    if (seen.has(normalized)) continue;
+
+    seen.add(normalized);
+    result.push(entry);
+  }
+
+  return result;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicate(record.ruledOut)) lines.push(`- ruled out: ${entry}`);
+    for (const entry of deduplicate(record.limits)) lines.push(`- limit: ${entry}`);
+    for (const entry of deduplicate(record.warns)) lines.push(`- warn: ${entry}`);
   }
   return lines.join("\n");
 };
